WITH base AS (SELECT id, account_id, txn_type, amount, txn_time, is_flagged, CONCAT(merchant, ' ', txn_type) AS merchant_txn_type, CASE WHEN is_flagged THEN 'Yes' ELSE 'No' END AS is_flagged_label FROM transactions WHERE merchant IS NOT NULL AND amount >= 3800), gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM base), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT txn_type, session_no, COUNT(*) AS cnt, MIN(session_start_flag) AS min_session_start_flag FROM sessions_transactions GROUP BY txn_type, session_no;
